      <div class="tabs">
        <button class="tab active" data-tab="festivals">Festivals & Events</button>
        <button class="tab" data-tab="theme-parks">Theme Parks</button>
        <button class="tab" data-tab="beaches">Beaches & Relaxation</button>
        <button class="tab" data-tab="cultural">Cultural Trips</button>
        <button class="tab" data-tab="food">Food & Cooking</button>
        <button class="tab" data-tab="city">City Exploration</button>
        <button class="tab" data-tab="wine">Wine Tastings</button>
        <button class="tab" data-tab="outdoor">Outdoor Adventures</button>
        <button class="tab" data-tab="nature">Nature Adventures</button>
        <button class="tab" data-tab="historical">Historical Tours</button>
