      <div class="destination-cards">
        <div class="dest-card">
          <div class="dest-card-img"><i class="ri-landscape-line"></i></div>
          <div class="dest-card-body">
            <h4>Pasadena</h4>
            <p>6 mi away</p>
          </div>
        </div>
        <div class="dest-card">
          <div class="dest-card-img"><i class="ri-building-line"></i></div>
          <div class="dest-card-body">
            <h4>Los Angeles</h4>
            <p>12 mi away</p>
